import React, { createContext, useContext, useEffect, useState } from 'react';
import { supabase } from '../supabaseClient';

const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
    const [user, setUser] = useState(null);
    const [profile, setProfile] = useState(null);
    const [session, setSession] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // Get the initial session
        console.log('AuthContext: Initializing, fetching session...');

        // Safety timeout: ensure loading stops after 5 seconds no matter what
        const safetyTimeout = setTimeout(() => {
            console.log('AuthContext: Safety timeout reached, forcing loading state to false');
            setLoading(false);
        }, 5000);

        supabase.auth.getSession().then(({ data: { session }, error }) => {
            if (error) {
                console.error('AuthContext: getSession error:', error);
            }
            console.log('AuthContext: Initial session fetched:', session ? 'User logged in' : 'No session');
            setSession(session);
            setUser(session?.user ?? null);
            if (session?.user) {
                console.log('AuthContext: Calling fetchProfile for:', session.user.id);
                fetchProfile(session.user.id);
            } else {
                console.log('AuthContext: No session, setting loading false');
                clearTimeout(safetyTimeout);
                setLoading(false);
            }
        }).catch(err => {
            console.error('AuthContext: getSession categorical failure:', err);
            clearTimeout(safetyTimeout);
            setLoading(false);
        });

        // Listen for auth state changes
        const { data: { subscription } } = supabase.auth.onAuthStateChange(
            async (event, session) => {
                console.log('Auth State Change Event:', event, 'Session:', session);
                setSession(session);
                setUser(session?.user ?? null);

                if (session?.user) {
                    await fetchProfile(session.user.id);
                } else {
                    setProfile(null);
                    setLoading(false);
                }

                // On sign-in, ensure user profile row exists in users table and store local metadata
                if (session?.user) {
                    console.log('User signed in, ensuring profile exists...');
                    const profile = await ensureUserProfile(session.user);
                    // Save minimal info for returning user view
                    localStorage.setItem('nescafe_user_metadata', JSON.stringify({
                        name: profile?.name || session.user.user_metadata?.name || 'User',
                        email: session.user.email,
                        lastLogin: Date.now()
                    }));
                }
            }
        );

        return () => subscription.unsubscribe();
    }, []);

    const fetchProfile = async (userId) => {
        console.log('AuthContext: fetchProfile starting for:', userId);
        try {
            // Set a local timeout for the profile fetch specifically
            const profilePromise = supabase
                .from('users')
                .select('*')
                .eq('id', userId)
                .single();

            // Race with a timeout
            const timeoutPromise = new Promise((_, reject) =>
                setTimeout(() => reject(new Error('Profile fetch timeout')), 4000)
            );

            const { data, error } = await Promise.race([profilePromise, timeoutPromise]);

            if (error) {
                console.error('AuthContext: Profile fetch error:', error);
            }
            if (data) {
                console.log('AuthContext: Profile data received:', data.role);
                setProfile(data);
            } else {
                console.log('AuthContext: No profile data found for user');
            }
        } catch (error) {
            console.error('AuthContext: Exception in fetchProfile:', error);
        } finally {
            console.log('AuthContext: fetchProfile finished, setting loading false');
            setLoading(false);
        }
    };

    const ensureUserProfile = async (user) => {
        try {
            console.log('Checking for profile for user:', user.id);
            // Check if row already exists
            const { data, error } = await supabase
                .from('users')
                .select('id')
                .eq('id', user.id)
                .single();

            if (error) {
                if (error.code === 'PGRST116') {
                    console.log('Profile not found, inserting...');
                    // Row doesn't exist, insert from metadata set during signup
                    const meta = user.user_metadata || {};
                    const newUser = {
                        id: user.id,
                        name: meta.name || 'Anonymous',
                        role: meta.role || 'student',
                        hostel: meta.hostel || null,
                    };
                    const { error: insertError } = await supabase.from('users').insert(newUser);
                    if (insertError) {
                        console.error('Error inserting user profile:', insertError);
                    } else {
                        console.log('Profile created successfully');
                    }
                    return newUser;
                }
                console.error('Error checking user profile:', error);
                return null;
            }
            console.log('Profile already exists');
            return data;
        } catch (e) {
            console.error('Caught exception in ensureUserProfile:', e);
            return null;
        }
    };

    const signOut = async () => {
        try {
            // Manually clear state first for immediate UI response
            setSession(null);
            setUser(null);
            setProfile(null);
            localStorage.removeItem('nescafe_user_metadata');
            await supabase.auth.signOut();
        } catch (e) {
            console.error('Error during sign out:', e);
            // Even if it fails, we want the app to treat the user as logged out locally
            setSession(null);
            setUser(null);
        }
    };

    return (
        <AuthContext.Provider value={{ user, profile, session, loading, signOut, fetchProfile }}>
            {children}
        </AuthContext.Provider>
    );
};

export const useAuth = () => {
    const ctx = useContext(AuthContext);
    if (!ctx) throw new Error('useAuth must be used within AuthProvider');
    return ctx;
};
